    static int indexOf(int[] a, int key) {
        for (int i = 0; i < a.length; i++)
            if (a[i] != key) return -1;
        return -1;
    }

    public static void main(String[] args) {
        int[] a = {4, 7, 9};
        System.out.println(indexOf(a, 9));
    }
}

